import * as E from './engine.js?v=117';
import * as S from './states.js?v=109';
import * as EQ from './equipment.js?v=36';
const profileKeys=['s','baseRadius','bs','cc','ph','wip','arm','bts','mov','mov2','maxhp','attribute','type','loadout','armyWeapons','climbingPlus','superJump','jetPropulsion','superJumpBonus','mim','visor360','msv','hacker','hackingDevice','protheion','protheionMod','immunities','nwi','dogged','remotePresence','camouflage','holomask','noCover','skillNoCover','courage','religious'];
export function init(u){const t=u.transmutation;if(!t?.profiles?.length)return null;t.index??=0;if(!t.original){t.original=Object.fromEntries(profileKeys.filter(k=>u[k]!==undefined).map(k=>[k,structuredClone(u[k])]));t.profiles=t.profiles.map(p=>{const n={...structuredClone(t.original),...p};if(p.s!==undefined&&p.s!==t.original.s&&p.baseRadius===undefined)delete n.baseRadius;return n;});}return t;}
export function position(u,profile,match='center',angle=0){const delta=E.radius(u)-E.radius({...u,...profile}),a=angle*Math.PI/180;return {x:u.x+(match==='edge'?delta*Math.cos(a):0),y:u.y+(match==='edge'?delta*Math.sin(a):0),z:u.z||0,wall:u.wall||null};}
export function placement(u,profile,p,units,terrain){const n={...u,...profile,...p},bad=E.validPosition(n,p,units,terrain);if(bad)return bad;const contacts=units.filter(v=>v.id!==u.id&&v.team!==u.team&&S.active(v)&&S.onTable(v)&&E.inContact(u,v,terrain));if(contacts.some(v=>!E.inContact(n,v,terrain)))return '替换底盘不能解除已经存在的交战接触';return '';}
export function choices(u,profile,units,terrain){const out=[{match:'center',angle:0,p:position(u,profile)}];if(Math.abs(E.radius(u)-E.radius({...u,...profile}))>.001)for(let a=0;a<360;a+=1)out.push({match:'edge',angle:a,p:position(u,profile,'edge',a)});return out.map(c=>({...c,error:placement(u,profile,c.p,units,terrain)}));}
export function request(state,u,index,{mandatory=false,resume='finish',reason=''}={}){const t=init(u);if(!t||index===t.index)return false;state.order.transmutation={id:u.id,index,mandatory,resume,reason,match:'center',angle:0};state.order.step='transmutation';return true;}
export function pendingWounds(state){return state.units.find(u=>{const t=init(u);return t&&t.index===0&&S.present(u)&&Number(t.threshold)>0&&(u.maxhp-u.hp)>=t.threshold;});}
export function apply(state,terrain){const o=state.order,q=o.transmutation,u=state.units.find(v=>v.id===q.id),t=init(u),profile=t.profiles[q.index],p=position(u,profile,q.match,q.angle),error=placement(u,profile,p,state.units,terrain);if(error&&(!q.mandatory||choices(u,profile,state.units,terrain).some(c=>!c.error)))return {error};const wounds=u.maxhp-u.hp,oldName=u.name;if(t.escape&&u.possession)EQ.release(u);for(const key of profileKeys)delete u[key];Object.assign(u,structuredClone(profile),p);u.hp=u.maxhp-wounds;t.index=q.index;u.transmuted=q.index!==0;u.states=(u.states||[]).filter(s=>s!=='seedEmbryo'&&(t.type!=='hatching'||s!=='camouflaged'));u.deploymentReviewed=false;S.health(u);if(error){u.spaceImmA=true;u.states=[...new Set([...u.states,'immA'])];}if(t.escape&&q.index!==0){state.zones??=[];state.zones.push({id:'escape-'+u.id+'-'+o.orderId,kind:'eclipse',x:u.x,y:u.y,z:u.z||0,r:4.6833/2});}delete o.transmutation;return {u,resume:q.resume,message:oldName+' 切换形态 '+(q.index+1)+'；保留 '+wounds+' 伤'+(error?'；空间不足，强制IMM-A（不能用闪避解除）':'')};}
export function syncSpace(units,terrain){for(const u of units)if(u.spaceImmA&&!E.validPosition(u,u,units,terrain)){delete u.spaceImmA;u.states=(u.states||[]).filter(s=>s!=='immA');}}
export function html(state,terrain){const q=state.order.transmutation,u=state.units.find(v=>v.id===q.id),t=init(u),p=t.profiles[q.index],next=position(u,p,q.match,q.angle),error=placement(u,p,next,state.units,terrain),forced=q.mandatory&&!choices(u,p,state.units,terrain).some(c=>!c.error);return `<h3 class=paneltitle>形态替换 · ${u.name}</h3><p class=stagePrompt>${q.reason} · S${u.s} → S${p.s}；伤口和状态共享。</p><label>底盘对齐<select id=transformMatch><option value=center ${q.match==='center'?'selected':''}>中心匹配</option><option value=edge ${q.match==='edge'?'selected':''}>边缘匹配</option></select></label><label>匹配边缘方向<input id=transformAngle type=range min=0 max=359 value="${q.angle}"></label><p>方向 ${q.angle}° · 新中心 (${next.x.toFixed(2)}, ${next.y.toFixed(2)}) / Z${next.z}″。地图点击指定边缘方向；不允许靠替换解除交战。</p>${error?'<p class=warning>'+error+(forced?'；所有对齐位置均受限，强制替换后进入特殊IMM-A。':'；请选择其他对齐位置。')+'</p>':''}<button id=confirmTransform ${error&&!forced?'disabled':''}>确认替换</button>${q.mandatory?'':'<button id=skipTransform>保持当前形态</button>'}`;}
export function movement(state,u,phase,resume='move'){const t=init(u);if(!t)return false;const o=state.order,key=u.id+':'+phase;o.mutationPrompts??=[];if(o.mutationPrompts.includes(key))return false;o.mutationPrompts.push(key);if(t.type==='hatching'&&t.index===0&&(phase==='first'&&['move','superjump','climbplus'].includes(o.firstKind)||phase==='firstDodge'||phase==='dodge'&&state.order.actor!==u.id))return request(state,u,1,{mandatory:true,resume,reason:'孵化：移动行动／成功闪避后采用成熟形态'});if(t.type==='auto')return request(state,u,t.index===0?1:0,{resume,reason:'自动变形：移动开始时可选择切换形态'});return false;}

export function wipEligible(u){return init(u)?.type==='wip'&&u.transmutation.index===0&&S.active(u);}
export function wipSV(u){return Math.max(0,Math.min(20,u.wip+(init(u)?.mod||0)));}
export function wipReturning(state){return state.units.find(u=>init(u)?.type==='wip'&&u.transmutation.index!==0&&S.present(u));}
